create extension if not exists "pgcrypto";
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,city text,state text,created_at timestamptz default now());
create table public.parishes(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,city text not null,state text not null,address text,phone text,verified boolean default false,created_at timestamptz default now());
create table public.parish_members(parish_id uuid references public.parishes(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text default 'follower',is_primary boolean default false,created_at timestamptz default now(),primary key(parish_id,user_id));
create table public.mass_schedules(id uuid primary key default gen_random_uuid(),parish_id uuid references public.parishes(id) on delete cascade,weekday smallint check(weekday between 0 and 6),starts_at time not null,label text);
create table public.daily_devotionals(id uuid primary key default gen_random_uuid(),devotional_date date unique not null,title text not null,scripture_reference text,scripture_excerpt text,reflection text not null,prayer text not null,purpose text,audio_url text,published boolean default false,created_at timestamptz default now());
create table public.devotional_completions(user_id uuid references public.profiles(id) on delete cascade,devotional_id uuid references public.daily_devotionals(id) on delete cascade,completed_at timestamptz default now(),primary key(user_id,devotional_id));
create table public.events(id uuid primary key default gen_random_uuid(),parish_id uuid references public.parishes(id),title text not null,description text,starts_at timestamptz not null,ends_at timestamptz,location text,price_cents integer default 0,capacity integer,status text default 'draft',created_at timestamptz default now());
create table public.campaigns(id uuid primary key default gen_random_uuid(),parish_id uuid references public.parishes(id),title text not null,description text,goal_cents bigint,raised_cents bigint default 0,verified boolean default false,status text default 'draft',created_at timestamptz default now());
create table public.sellers(id uuid primary key default gen_random_uuid(),name text not null,verified boolean default false,commission_bps integer default 1500,created_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(),seller_id uuid references public.sellers(id),name text not null,slug text unique not null,category text not null,description text,price_cents integer not null,stock integer,active boolean default true,created_at timestamptz default now());
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id),status text default 'pending',subtotal_cents integer not null default 0,platform_fee_cents integer not null default 0,parish_share_cents integer not null default 0,total_cents integer not null default 0,created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.parishes enable row level security;alter table public.daily_devotionals enable row level security;alter table public.events enable row level security;alter table public.campaigns enable row level security;alter table public.products enable row level security;alter table public.orders enable row level security;alter table public.devotional_completions enable row level security;
create policy "public parishes readable" on public.parishes for select using(true);create policy "published devotionals readable" on public.daily_devotionals for select using(published=true);create policy "public events readable" on public.events for select using(status='published');create policy "public campaigns readable" on public.campaigns for select using(status='published');create policy "active products readable" on public.products for select using(active=true);create policy "own profile readable" on public.profiles for select using(auth.uid()=id);create policy "own completions" on public.devotional_completions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own orders readable" on public.orders for select using(auth.uid()=user_id);
